using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Research Agent – a .NET 10 console app that uses an AI agent with tools
// to research a topic on the web and summarize findings.
// ---------------------------------------------------------------------------

// --- Configuration --------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool instances -------------------------------------------------------

var notebook = new Notebook();
var webSearch = new WebSearchTool();

// --- Build the chat client with tool support ------------------------------

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(webSearch.SearchWeb),
        AIFunctionFactory.Create(webSearch.FetchPage),
        AIFunctionFactory.Create(notebook.AddNote),
        AIFunctionFactory.Create(notebook.GetNotes),
    ]
};

// --- Prompt the user ------------------------------------------------------

Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

// --- Run the agent loop ---------------------------------------------------

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Yellow;
Console.WriteLine($"Researching: {topic}");
Console.ResetColor();
Console.WriteLine();

var systemPrompt = $"""
    You are a research agent. Your goal is to thoroughly research the following topic
    and produce a well-structured summary.

    Topic: {topic}

    Instructions:
    1. Use the SearchWeb tool to find relevant information about the topic.
    2. Use the FetchPage tool to read promising pages from the search results.
    3. Use the AddNote tool to save key facts, quotes, and insights as you go.
    4. Use the GetNotes tool to review what you have collected so far.
    5. After gathering enough information (at least 3-5 good sources), produce a
       final summary that synthesizes your notes into a coherent, informative report.

    When you are done researching, write your final summary as your last message.
    Start the summary with "## Research Summary" so it is easy to identify.
    """;

List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the following topic: {topic}")
];

var response = await client.GetResponseAsync(messages, chatOptions);

// --- Display the final summary --------------------------------------------

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("─── Agent Response ───────────────────────────────");
Console.ResetColor();
Console.WriteLine(response.Text);
Console.WriteLine();

if (notebook.Notes.Count > 0)
{
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"({notebook.Notes.Count} notes collected during research)");
    Console.ResetColor();
}

// ===========================================================================
// Tool: Web Search (uses Brave Search API with fallback to HTML scraping)
// ===========================================================================

public sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html,application/xhtml+xml,application/json" }
        }
    };

    [Description("Search the web for a query and return a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: {query}");
        Console.ResetColor();

        // Try Brave Search API if key is available
        var braveKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
        if (!string.IsNullOrEmpty(braveKey))
        {
            try
            {
                return await BraveSearch(query, braveKey);
            }
            catch
            {
                // Fall through to scraping
            }
        }

        // Fallback: scrape DuckDuckGo lite
        return await DuckDuckGoSearch(query);
    }

    [Description("Fetch the text content of a web page given its URL. Returns the page text (truncated to ~4000 chars).")]
    public async Task<string> FetchPage(
        [Description("The full URL to fetch")] string url)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🌐 Fetching: {url}");
        Console.ResetColor();

        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            return text.Length > 4000 ? text[..4000] + "\n...(truncated)" : text;
        }
        catch (Exception ex)
        {
            return $"Error fetching page: {ex.Message}";
        }
    }

    private static async Task<string> BraveSearch(string query, string apiKey)
    {
        var encoded = WebUtility.UrlEncode(query);
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={encoded}&count=5");
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        var response = await Http.SendAsync(request);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync();

        using var doc = JsonDocument.Parse(json);
        var results = doc.RootElement.GetProperty("web").GetProperty("results");

        var sb = new StringBuilder();
        foreach (var r in results.EnumerateArray())
        {
            var title = r.GetProperty("title").GetString();
            var link = r.GetProperty("url").GetString();
            var snippet = r.TryGetProperty("description", out var d)
                ? d.GetString() : "";
            sb.AppendLine($"- **{title}**");
            sb.AppendLine($"  URL: {link}");
            sb.AppendLine($"  {snippet}");
            sb.AppendLine();
        }
        return sb.Length > 0 ? sb.ToString() : "No results found.";
    }

    private static async Task<string> DuckDuckGoSearch(string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);

            return text.Length > 3000
                ? text[..3000] + "\n...(truncated)"
                : (text.Length > 50 ? text : "No results found. Try a different query.");
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try using FetchPage directly with a known URL.";
        }
    }

    private static string StripHtml(string html)
    {
        // Remove script/style blocks
        var cleaned = Regex.Replace(html, @"<(script|style)[^>]*>[\s\S]*?</\1>", " ",
            RegexOptions.IgnoreCase);
        // Remove tags
        cleaned = Regex.Replace(cleaned, @"<[^>]+>", " ");
        // Decode entities
        cleaned = WebUtility.HtmlDecode(cleaned);
        // Collapse whitespace
        cleaned = Regex.Replace(cleaned, @"\s+", " ").Trim();
        return cleaned;
    }
}

// ===========================================================================
// Tool: Notebook – lets the agent collect and review research notes
// ===========================================================================

public sealed class Notebook
{
    public List<string> Notes { get; } = [];

    [Description("Add a research note. Use this to record key facts, insights, or quotes found during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note #{Notes.Count} saved");
        Console.ResetColor();
        return $"Note #{Notes.Count} saved successfully.";
    }

    [Description("Retrieve all research notes collected so far.")]
    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < Notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {Notes[i]}");
        return sb.ToString();
    }
}

